import{_ as i,l as s,o as e,c as l,v as t,p as n,x as r,d,i as E,S as h}from"./chunks/framework.InCnrqk-.js";const b=JSON.parse('{"title":"连接算法","description":"","frontmatter":{"title":"连接算法","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/join-algorithms.md","filePath":"cs/join-algorithms.md","lastUpdated":1789023840000}'),c={name:"cs/join-algorithms.md"};function p(m,a,A,_,B,f){const o=s("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="连接算法" tabindex="-1">连接算法 <a class="header-anchor" href="#连接算法" aria-label="Permalink to &quot;连接算法&quot;">​</a></h1><div class="epigraph"><p>逻辑连接只有一种含义；物理上嵌套循环、排序归并与哈希是三种不同的 I/O 形状。</p><footer>—— 据 Blasgen and Eswaran, 1977；Ramakrishnan and Gehrke 对连接算子的整理</footer></div><p><a href="/cs/sql-null">上一课</a>把查询钉成声明：含义在代数，不在扫描顺序。本课不重写 <code>SELECT</code>。缺口是：\\(\\bowtie\\) 在磁盘上怎么算。元组在<a href="/cs/file-bytestream">文件</a>里，页经<a href="/cs/buffer-dirty">缓冲</a>进出内存；连接算法决定读多少页、要不要排序、要不要建哈希表。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>两表等值连接的指称是「键值相等的元组对」。实现若只会双重循环扫全表，大表上不可用。缺口不是新的关系运算，而是三种经典物理算子：嵌套循环（可带索引）、排序归并、哈希连接。本课不选优化器，只把每种算子的 I/O 形状交给后课计划。</p><p><span class="marginnote">外存代价按页计，不是按元组计。<a href="/cs/btree-external">B 树</a>已经能按键定位；索引嵌套循环就是「外层每条探针走一次索引」，不是另一种逻辑连接。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>嵌套循环：对外层每一元组（或每一页）扫描内层。有索引时，内层查找从全表变成点查或范围查。排序归并：两输入按连接键排序（或已有序），然后一次归并扫描。哈希连接：把较小一侧建成内存哈希表（或分区后逐桶建表），另一侧探针。</p>',8)),(e(),n(h,null,{default:r(()=>[E(o,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20JOIN%5B%22%E9%80%BB%E8%BE%91%20%E2%8B%88%22%5D%20--%3E%20NL%5B%22%E5%B5%8C%E5%A5%97%E5%BE%AA%E7%8E%AF%20%2F%20%E7%B4%A2%E5%BC%95%E5%BE%AA%E7%8E%AF%22%5D%0A%20%20JOIN%20--%3E%20SM%5B%22%E6%8E%92%E5%BA%8F%E5%BD%92%E5%B9%B6%22%5D%0A%20%20JOIN%20--%3E%20HJ%5B%22%E5%93%88%E5%B8%8C%E8%BF%9E%E6%8E%A5%22%5D%0A%20%20NL%20--%3E%20PLAN%5B%22%E5%90%8E%E8%AF%BE%3A%20%E6%9F%A5%E8%AF%A2%E8%AE%A1%E5%88%92%22%5D%0A%20%20SM%20--%3E%20PLAN%0A%20%20HJ%20--%3E%20PLAN%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>三种算子实现同一指称，代价形状不同。嵌套循环对高度选择的探针便宜，对两次全表笛卡尔积式扫描极贵。排序归并吃排序的 \\(I/O\\)，但输出自然有序，可供后继归并或 <code>ORDER BY</code> 免排。哈希连接对等值连接通常最少随机 I/O，但不等值、范围连接用不上；内存不够时要分区，回退成多趟。</p><p>块嵌套循环把「元组对元组」改成「页对页」，缓冲池命中率决定常数。本课不引入并行 hash join 的全部划分协议，只要求：算子是计划树的节点，有输入基数与内存预算。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写代价公式的数字表，那是<a href="/cs/cost-estimate">代价估计</a>。也不处理星型、迟物化、索引下推的全部变体。外连接、半连接是同一族算子加标记，语义缺口已在代数/SQL，这里只承认物理上多一条空匹配路径。</p><p>多表连接是两两算子的树，不是一个 \\(n\\) 路魔法；谁与谁先连，由后课计划决定。后课默认：谈到连接，逻辑一层、物理三族；计划树从这些算子里挑，而不是从文件循环里现场发明。</p><p>三种算子都可以流水线或物化；哈希建表是物化点，索引循环更像探针。后课计划树把这些点标出来，本课只要求认得 I/O 形状。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>声明已在；本课只交出嵌套循环、排序归并、哈希三种 I/O 形状。</li><li>索引嵌套循环复用 B 树，不是新模型。</li><li>选哪一种是后课计划与代价的缺口。</li><li>出处：Blasgen and Eswaran, 1977；Garcia-Molina, Ullman and Widom；Ramakrishnan and Gehrke。</li></ul>',9))])}const T=i(c,[["render",p]]);export{b as __pageData,T as default};
